1	import React, { useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	import { useJsonResource } from '../../ui/useJsonResource';
4	
5	// Clients feature: add a client (name + email) and list every client. Opening a client
6	// (client-open-<id>) reveals the projects being done for them — the client's own projects listing,
7	// scoped via its /api/clients/<id>/projects endpoint. Owns its own state; talks to its own
8	// /api/clients endpoints. data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string; outstanding: number };
10	// How the clients list is ordered: alphabetically by name, or by how much each client still owes.
11	type SortKey = 'name' | 'outstanding';
12	type Project = { id: number; name: string; clientId: number; clientName: string };
13	type Contact = {
14	  id: number;
15	  clientId: number;
16	  name: string;
17	  email: string;
18	  role: string;
19	  primary: boolean;
20	};
21	type ClientSummary = { projectCount: number; contactCount: number };
22	type StatementInvoice = { id: number; projectId: number; amountDue: number };
23	type ClientStatement = { invoices: StatementInvoice[]; outstandingTotal: number };
24	
25	// Money, the way every invoice figure is shown across the app: a dollar sign and two decimals.
26	function money(amount: number): string {
27	  return `$${Number(amount).toLocaleString('en-US', {
28	    minimumFractionDigits: 2,
29	    maximumFractionDigits: 2,
30	  })}`;
31	}
32	
33	// Every client (and contact) needs a proper email. Same shape the server enforces (see CreateClient
34	// / CreateContact) so the UI and the API agree on what "valid" means.
35	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
36	function isValidEmail(value: string): boolean {
37	  return EMAIL_RE.test(value.trim());
38	}
39	
40	// A client's statement: all of their invoices in one place, each with what is still owed on it, and
41	// the total still owed across them all. Kept behind an opener so the client detail stays compact.
42	// Owns its own statement state, scoped to the one client it is showing; talks to that client's own
43	// /api/clients/<id>/statement endpoint.
44	function ClientStatement({ client }: { client: Client }) {
45	  const [statement] = useJsonResource<ClientStatement | null>(
46	    `/api/clients/${client.id}/statement`,
47	    null,
48	  );
49	  const [open, setOpen] = useState(false);
50	
51	  return (
52	    <section data-testid="client-statement">
53	      <button data-testid="client-statement-open" onClick={() => setOpen(true)}>
54	        Statement
55	      </button>
56	      {open && statement && (
57	        <>
58	          <table data-testid="client-statement-table">
59	            <tbody>
60	              {statement.invoices.map((inv) => (
61	                <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
62	                  <td data-testid="statement-invoice-due">{money(inv.amountDue)}</td>
63	                </tr>
64	              ))}
65	            </tbody>
66	          </table>
67	          <p data-testid="client-outstanding-total">{money(statement.outstandingTotal)}</p>
68	        </>
69	      )}
70	    </section>
71	  );
72	}
73	
74	// Recording one lump sum a client paid, split across several of their open invoices. Opening the
75	// form lists each open invoice with a box for the share of the lump sum applied to it
76	// (payment-alloc-<invoiceId>); submitting records one payment per share, so every invoice's balance
77	// then reflects what was put against it. Owns its own form state, scoped to the one client; reads the
78	// client's statement for the open invoices and talks to that client's own /api/clients/<id>/payments
79	// endpoint.
80	function ClientPayment({ client }: { client: Client }) {
81	  const [statement, reload] = useJsonResource<ClientStatement | null>(
82	    `/api/clients/${client.id}/statement`,
83	    null,
84	  );
85	  const [open, setOpen] = useState(false);
86	  const [amount, setAmount] = useState('');
87	  const [date, setDate] = useState('');
88	  // The share typed against each invoice, held as raw strings keyed by invoice id so the inputs stay
89	  // controlled.
90	  const [allocations, setAllocations] = useState<Record<number, string>>({});
91	
92	  const openInvoices = (statement?.invoices ?? []).filter((inv) => inv.amountDue > 0);
93	
94	  async function submit(e: React.FormEvent) {
95	    e.preventDefault();
96	    if (date.trim() === '') {
97	      return;
98	    }
99	    const shares = openInvoices
100	      .map((inv) => ({ invoiceId: inv.id, amount: Number(allocations[inv.id]) }))
101	      .filter((s) => Number.isFinite(s.amount) && s.amount > 0);
102	    if (shares.length === 0) {
103	      return;
104	    }
105	    await fetch(`/api/clients/${client.id}/payments`, {
106	      method: 'POST',
107	      headers: { 'Content-Type': 'application/json' },
108	      body: JSON.stringify({ amount: Number(amount), date, allocations: shares }),
109	    });
110	    setOpen(false);
111	    setAmount('');
112	    setDate('');
113	    setAllocations({});
114	    await reload();
115	  }
116	
117	  return (
118	    <section data-testid="client-payment">
119	      <button data-testid="client-record-payment" type="button" onClick={() => setOpen(true)}>
120	        Record payment
121	      </button>
122	      {open && (
123	        <form data-testid="payment-form" onSubmit={submit}>
124	          <input
125	            data-testid="payment-form-amount"
126	            placeholder="Amount paid"
127	            value={amount}
128	            onChange={(e) => setAmount(e.target.value)}
129	          />
130	          <input
131	            data-testid="payment-form-date"
132	            type="date"
133	            value={date}
134	            onChange={(e) => setDate(e.target.value)}
135	          />
136	          <table data-testid="payment-alloc-table">
137	            <tbody>
138	              {openInvoices.map((inv) => (
139	                <tr key={inv.id} data-testid={`payment-alloc-row-${inv.id}`}>
140	                  <td data-testid="payment-alloc-due">{money(inv.amountDue)}</td>
141	                  <td>
142	                    <input
143	                      data-testid={`payment-alloc-${inv.id}`}
144	                      placeholder="Applied to this invoice"
145	                      value={allocations[inv.id] ?? ''}
146	                      onChange={(e) =>
147	                        setAllocations((prev) => ({ ...prev, [inv.id]: e.target.value }))
148	                      }
149	                    />
150	                  </td>
151	                </tr>
152	              ))}
153	            </tbody>
154	          </table>
155	          <button data-testid="payment-form-submit" type="submit">
156	            Record payment
157	          </button>
158	        </form>
159	      )}
160	    </section>
161	  );
162	}
163	
164	// A client's at-a-glance counts: how many projects and contacts are kept for them. Owns its own
165	// summary state, scoped to the one client it is showing; talks to that client's own
166	// /api/clients/<id>/summary endpoint.
167	function ClientSummaryBadges({ client }: { client: Client }) {
168	  const [summary] = useJsonResource<ClientSummary>(`/api/clients/${client.id}/summary`, {
169	    projectCount: 0,
170	    contactCount: 0,
171	  });
172	
173	  return (
174	    <section data-testid="client-summary">
175	      <span data-testid="client-projects-count">{summary.projectCount}</span>
176	      <span data-testid="client-contacts-count">{summary.contactCount}</span>
177	    </section>
178	  );
179	}
180	
181	// The add-a-contact form: name, email and role, all required, with the same email check the server
182	// runs. Owns only its own field state and clears itself once the parent has taken the new contact.
183	function ContactForm({
184	  onAdd,
185	}: {
186	  onAdd: (contact: { name: string; email: string; role: string }) => Promise<void>;
187	}) {
188	  const [name, setName] = useState('');
189	  const [email, setEmail] = useState('');
190	  const [role, setRole] = useState('');
191	  const [emailError, setEmailError] = useState('');
192	
193	  async function submit(e: React.FormEvent) {
194	    e.preventDefault();
195	    if (!name.trim() || !email.trim() || !role.trim()) {
196	      return;
197	    }
198	    if (!isValidEmail(email)) {
199	      setEmailError('Enter a valid email address.');
200	      return;
201	    }
202	    setEmailError('');
203	    await onAdd({ name, email, role });
204	    setName('');
205	    setEmail('');
206	    setRole('');
207	  }
208	
209	  return (
210	    <form data-testid="contact-form" onSubmit={submit}>
211	      <input
212	        data-testid="contact-form-name"
213	        placeholder="Name"
214	        value={name}
215	        onChange={(e) => setName(e.target.value)}
216	      />
217	      <input
218	        data-testid="contact-form-email"
219	        placeholder="Email"
220	        value={email}
221	        onChange={(e) => setEmail(e.target.value)}
222	      />
223	      {emailError && (
224	        <p data-testid="contact-form-email-error" role="alert">
225	          {emailError}
226	        </p>
227	      )}
228	      <input
229	        data-testid="contact-form-role"
230	        placeholder="Role"
231	        value={role}
232	        onChange={(e) => setRole(e.target.value)}
233	      />
234	      <button data-testid="contact-form-submit" type="submit">
235	        Add contact
236	      </button>
237	    </form>
238	  );
239	}
240	
241	// The contacts list itself: a row per contact with a control to promote it to the client's primary.
242	function ContactsTable({
243	  contacts,
244	  onMakePrimary,
245	}: {
246	  contacts: Contact[];
247	  onMakePrimary: (id: number) => void;
248	}) {
249	  return (
250	    <table data-testid="client-contacts-table">
251	      <tbody>
252	        {contacts.map((ct) => (
253	          <tr key={ct.id} data-testid={`contact-row-${ct.id}`}>
254	            <td data-testid="contact-name">{ct.name}</td>
255	            <td data-testid="contact-email">{ct.email}</td>
256	            <td data-testid="contact-role">{ct.role}</td>
257	            <td>
258	              <button data-testid={`contact-primary-${ct.id}`} onClick={() => onMakePrimary(ct.id)}>
259	                Make primary
260	              </button>
261	            </td>
262	          </tr>
263	        ))}
264	      </tbody>
265	    </table>
266	  );
267	}
268	
269	// A client's contacts: the people the user keeps for them (name, email, role), with a form to add
270	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
271	// client's own /api/clients/<id>/contacts endpoints. The form and the table are their own pieces so
272	// this stays a thin coordinator: load, add, promote, show who is primary.
273	function ClientContacts({ client }: { client: Client }) {
274	  const [contacts, reload] = useJsonResource<Contact[]>(`/api/clients/${client.id}/contacts`, []);
275	
276	  async function addContact(contact: { name: string; email: string; role: string }) {
277	    await fetch(`/api/clients/${client.id}/contacts`, {
278	      method: 'POST',
279	      headers: { 'Content-Type': 'application/json' },
280	      body: JSON.stringify(contact),
281	    });
282	    await reload();
283	  }
284	
285	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
286	  async function makePrimary(id: number) {
287	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
288	    await reload();
289	  }
290	
291	  const primary = contacts.find((ct) => ct.primary) ?? null;
292	
293	  return (
294	    <section data-testid="client-contacts">
295	      <p data-testid="client-primary-contact">{primary ? primary.name : ''}</p>
296	      <ContactForm onAdd={addContact} />
297	      <ContactsTable contacts={contacts} onMakePrimary={makePrimary} />
298	    </section>
299	  );
300	}
301	
302	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
303	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
304	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
305	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
306	function ClientProjects({ client }: { client: Client }) {
307	  const [showAll, setShowAll] = useState(false);
308	  const [projects] = useJsonResource<Project[]>(
309	    `/api/clients/${client.id}/projects?scope=${showAll ? 'all' : 'active'}`,
310	    [],
311	  );
312	
313	  return (
314	    <section data-testid="client-projects">
315	      <button data-testid="client-projects-show-all" onClick={() => setShowAll((v) => !v)}>
316	        {showAll ? 'Show only active' : 'Show finished and hidden too'}
317	      </button>
318	      <table data-testid="client-projects-table">
319	        <tbody>
320	          {projects.map((p) => (
321	            <tr key={p.id} data-testid={`project-row-${p.id}`}>
322	              <td data-testid="project-name">{p.name}</td>
323	            </tr>
324	          ))}
325	        </tbody>
326	      </table>
327	    </section>
328	  );
329	}
330	
331	// A name-and-email form for a client, used to add one and reusable for correcting one. `testid` is
332	// the anchor prefix (its fields are `${testid}-name` / `-email` / `-email-error` / `-submit`), so a
333	// second instance (e.g. an edit form) just passes a different prefix. Validates the email format the
334	// way the server does; `onSubmit` returns an error string to show (e.g. a duplicate the server
335	// rejected) or null on success, in which case the form clears back to its initial values.
336	function ClientForm({
337	  testid,
338	  submitLabel,
339	  initial = { name: '', email: '' },
340	  onSubmit,
341	}: {
342	  testid: string;
343	  submitLabel: string;
344	  initial?: { name: string; email: string };
345	  onSubmit: (values: { name: string; email: string }) => Promise<string | null>;
346	}) {
347	  const [name, setName] = useState(initial.name);
348	  const [email, setEmail] = useState(initial.email);
349	  const [emailError, setEmailError] = useState('');
350	
351	  async function submit(e: React.FormEvent) {
352	    e.preventDefault();
353	    if (!isValidEmail(email)) {
354	      setEmailError('Enter a valid email address.');
355	      return;
356	    }
357	    const error = await onSubmit({ name, email });
358	    if (error) {
359	      setEmailError(error);
360	      return;
361	    }
362	    setEmailError('');
363	    setName(initial.name);
364	    setEmail(initial.email);
365	  }
366	
367	  return (
368	    <form data-testid={testid} onSubmit={submit}>
369	      <input
370	        data-testid={`${testid}-name`}
371	        placeholder="Name"
372	        value={name}
373	        onChange={(e) => setName(e.target.value)}
374	      />
375	      <input
376	        data-testid={`${testid}-email`}
377	        placeholder="Email"
378	        value={email}
379	        onChange={(e) => setEmail(e.target.value)}
380	      />
381	      {emailError && (
382	        <p data-testid={`${testid}-email-error`} role="alert">
383	          {emailError}
384	        </p>
385	      )}
386	      <button data-testid={`${testid}-submit`} type="submit">
387	        {submitLabel}
388	      </button>
389	    </form>
390	  );
391	}
392	
393	// The client list: a row per client with controls to open its detail or archive it.
394	function ClientsTable({
395	  clients,
396	  onOpen,
397	  onEdit,
398	  onArchive,
